insert into public.places (id, slug, name, group_id, category_id, region_id, address, phone, website, menu_url, image_url, image_source_url, image_attribution, image_checked_at, logo_url, logo_source_url, logo_checked_at, place_type, source_url, source_checked_at, map_url, data_notes, latitude, longitude, features, tags, service_details, is_active) values ('hot-spot-cycles', 'hot-spot-cycles', 'Hot Spot Cycles', null, 'shops', 'faerie-glen', 'Shop 3B, Atterbury Decor Centre, Windsor Road entrance at Atterbury Road, Faerie Glen, Pretoria, 0081', '012 993 5231', 'https://hotspotcycles.co.za/pages/contact', null, null, null, null, null, null, null, null, 'bicycle_shop', 'https://hotspotcycles.co.za/pages/contact', '2026-10-18', 'https://www.waze.com/live-map/directions/hotspot-cycles-windsor-rd-faerie-glen,-pretoria?to=place.w.18548230.185547837.7032509', 'Use the Windsor Road entrance. Operator lists shop 3B, Atterbury Decor Centre; a supplier search excerpt gives shop 2, Atterbury Lifestyle Centre, so confirm the shop before travelling. Waze supplies the business pin, not a verified doorway. Holiday hours differ from the weekly schedule.', -25.791607566, 28.310121893, '{}'::text[], array['Bicycles', 'Cycling', 'Accessories', 'Padel equipment']::text[], '{"shop":"3B","shopping_centre":"Atterbury Decor Centre","entrance":"Windsor Road at Atterbury Road","coordinate_source":"https://www.waze.com/live-map/directions/hotspot-cycles-windsor-rd-faerie-glen,-pretoria?to=place.w.18548230.185547837.7032509","coordinate_precision":"third_party_business_pin","branch_email":"info@hotspotcycles.co.za","alternate_phone":"012 993 4642","mobile_phone":"082 315 2991","public_holiday_hours":"Closed except when the holiday falls on Saturday; confirm that day''s hours.","hours_scope":"store","inventory_source":"https://hotspotcycles.co.za/","services":["Bicycle sales","Cycling accessories","Padel equipment"],"grouping_note":"One published business location; no chain group inferred from product brands.","supplier_search_excerpt_conflict":{"source":"https://bicyclepower.co.za/dealer-profiles/hot-spot-cycles/","address":"Shop 2, Atterbury Lifestyle Centre","verification":"Search excerpt only; operator contact page preferred."}}'::jsonb, false);
insert into public.places (id, slug, name, group_id, category_id, region_id, address, phone, website, menu_url, image_url, image_source_url, image_attribution, image_checked_at, logo_url, logo_source_url, logo_checked_at, place_type, source_url, source_checked_at, map_url, data_notes, latitude, longitude, features, tags, service_details, is_active) values ('lynnwood-cyclery', 'lynnwood-cyclery', 'Lynnwood Cyclery', null, 'shops', 'die-wilgers', 'Shop 1A, Willow Way Centre, Lynnwood Road, Pretoria East, 0184', '012 348 3132', 'https://www.lynnwoodcyclery.co.za/', null, null, null, null, null, null, null, null, 'bicycle_shop', 'https://www.lynnwoodcyclery.co.za/', '2026-10-18', 'https://www.google.com/maps/search/?api=1&query=Google&query_place_id=ChIJ7wUkqztelR4RI2I27Ol5PmU', 'Shop opening starts at 09:00. The operator separately lists bike drop-off from 07:00; confirm days and workshop bookings. Sunday closed; published holiday hours 09:00-12:00 need confirmation. Coordinates come from the operator''s address configuration and are not verified as a doorway. Willow Way Centre is in Die Wilgers; Lynnwood in the business name does not set the suburb.', -25.7652286, 28.3146425, '{}'::text[], array['Bicycles', 'Cycling', 'Accessories', 'Bicycle servicing', 'Bike fitting']::text[], '{"shop":"1A","shopping_centre":"Willow Way Centre","coordinate_source":"https://www.lynnwoodcyclery.co.za/","coordinate_precision":"operator_address_configuration","coordinate_context":"Shopify business address configuration matches the visible Willow Way Centre address.","locality_source":"https://www.waze.com/en-AU/live-map/directions/superspar-willow-way-centre,-lynnwood-rd-(m6)-die-wilgers,-pretoria?to=place.w.18548230.185613375.4788885","branch_email":"gert@lynnwoodcyclery.co.za","whatsapp":"063 626 6533","bike_drop_off":"From 07:00; days and workshop acceptance need confirmation. Not general shop opening.","public_holiday_hours":"09:00-12:00; confirm before travelling.","hours_scope":"store","services":["Bicycle sales","Bicycle servicing","Bike fitting"],"grouping_note":"Specialized concept store/dealer; do not infer a chain group from the bicycle manufacturer."}'::jsonb, false);
